-- Production document table columns and constraints inspected 2026-10-29.
-- No noninternal document-table triggers were present. Parent application is a fixture.
create table sos_hero_application_documents(id uuid default gen_random_uuid() not null,application_id uuid not null,auth_id uuid not null,document_type text not null,storage_path text not null,status text default 'submitted'::text not null,operator_note text,reviewed_at timestamptz,reviewed_by uuid,created_at timestamptz default now() not null,updated_at timestamptz default now() not null,constraint sos_hero_application_documents_application_id_fkey FOREIGN KEY (application_id) REFERENCES sos_hero_applications(id) ON DELETE CASCADE,constraint sos_hero_application_documents_document_type_check CHECK ((document_type = ANY (ARRAY['government_id'::text, 'drivers_license'::text, 'insurance'::text, 'vehicle_registration'::text, 'business_license'::text, 'certification'::text, 'vehicle_photo'::text, 'equipment_photo'::text, 'other'::text]))),constraint sos_hero_application_documents_pkey PRIMARY KEY (id),constraint sos_hero_application_documents_status_check CHECK ((status = ANY (ARRAY['submitted'::text, 'accepted'::text, 'rejected'::text]))),constraint sos_hero_application_documents_storage_path_key UNIQUE (storage_path));
